private void backtrack(int[] nums, boolean[] used, java.util.ArrayList<Integer> current, java.util.List<java.util.List<Integer>> res) {
    if (current.size() == nums.length) {
        res.add(new java.util.ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, res);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int numStrings = strings.size();
    String first = strings.get(0);
    int minLen = first.length();
    for (int i = 1; i < numStrings; i++) {
        minLen = Math.min(minLen, strings.get(i).length());
    }
    for (int len = minLen; len >= 1; len--) {
        String base = first;
        int baseLen = base.length();
        java.util.HashSet<String> candidates = new java.util.HashSet<>();
        for (int i = 0; i + len <= baseLen; i++) {
            String sub = base.substring(i, i + len);
            candidates.add(sub);
            candidates.add(new StringBuilder(sub).reverse().toString());
        }
        for (String cand : candidates) {
            String revCand = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (int idx = 0; idx < numStrings; idx++) {
                String s = strings.get(idx);
                if (!(s.contains(cand) || s.contains(revCand))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    int depositCount = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@') {
                depositCount++;
                // Depth-first search to mark all connected '@' cells
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                grid[r][c] = '*';
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0], cc = pos[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dr[k];
                        int nc = cc + dc[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '@') {
                            stack.push(new int[]{nr, nc});
                            grid[nr][nc] = '*';
                        }
                    }
                }
            }
        }
    }
    return depositCount;
}

