public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Build adjacency list from the given paths
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        String a = p[0] + "," + p[1];
        String b = p[2] + "," + p[3];
        adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }

    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];

    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.LinkedList<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = adj.getOrDefault(current, java.util.Collections.emptyList());
        for (String neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                if (neighbor.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    int[] f1 = new int[256];
    int[] f2 = new int[256];
    for (int i = 0; i < word1.length(); i++) {
        f1[word1.charAt(i)]++;
    }
    for (int i = 0; i < word2.length(); i++) {
        f2[word2.charAt(i)]++;
    }
    int common = 0;
    for (int i = 0; i < 256; i++) {
        common += Math.min(f1[i], f2[i]);
    }
    int numerator = 2 * common;
    int denominator = word1.length() + word2.length();
    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    int a = numerator, b = denominator;
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    int g = a;
    int numRed = numerator / g;
    int denRed = denominator / g;
    String value;
    if (denRed == 1) {
        value = Integer.toString(numRed);
    } else {
        value = numRed + "/" + denRed;
    }
    return "appx(" + word1 + ", " + word2 + ") = " + value;
}

