public boolean canArrange(int[] arr, int k) {
    // If array length is odd, cannot form n/2 pairs
    if (arr.length % 2 != 0) {
        return false;
    }

    java.util.Map<Integer, Integer> count = new java.util.HashMap<>();

    // Count remainders modulo k
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) {
            rem += k;
        }
        count.put(rem, count.getOrDefault(rem, 0) + 1);
    }

    // Check pairing conditions
    for (java.util.Map.Entry<Integer, Integer> entry : count.entrySet()) {
        int rem = entry.getKey();
        int freq = entry.getValue();
        int complement = (k - rem) % k;

        // Special cases: remainder 0 or, when k is even, remainder k/2
        if (rem == 0 || (k % 2 == 0 && rem == k / 2)) {
            if (freq % 2 != 0) {
                return false;
            }
        } else {
            int compFreq = count.getOrDefault(complement, 0);
            if (freq != compFreq) {
                return false;
            }
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    boolean[] visited = new boolean[n];
    return dfs(0, graph, visited, hasApple);
}

private int dfs(int node, List<Integer>[] graph, boolean[] visited, boolean[] hasApple) {
    visited[node] = true;
    int total = 0;
    for (int nei : graph[node]) {
        if (!visited[nei]) {
            int time = dfs(nei, graph, visited, hasApple);
            if (time > 0 || hasApple[nei]) {
                total += time + 2;
            }
        }
    }
    return total;
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        // Descending pass
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int total = 0;
    for (int num : nums) total += num;
    int half = n / 2;
    @SuppressWarnings("unchecked")
    ArrayList<HashSet<Integer>> dp = new ArrayList<>(half + 1);
    for (int i = 0; i <= half; i++) dp.add(new HashSet<>());
    dp.get(0).add(0);
    for (int num : nums) {
        for (int k = Math.min(half, dp.size() - 1); k >= 1; k--) {
            if (dp.get(k - 1).isEmpty()) continue;
            int target = total * k / n;
            if (total * k % n != 0) continue;
            for (int s : dp.get(k - 1)) {
                int newSum = s + num;
                if (newSum == target) return true;
                dp.get(k).add(newSum);
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int prev2 = cost[0];          // cost to reach step 0
    int prev1 = cost[1];          // cost to reach step 1

    for (int i = 2; i < n; i++) {
        int cur = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = cur;
    }

    return Math.min(prev1, prev2); // min cost to reach the top from last two steps
}

