public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = 0;
    for (int i = 0; i < k; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }
    seen[mask] = true;
    int maskLimit = total - 1;
    for (int i = k; i < n; i++) {
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        seen[mask] = true;
    }
    for (boolean v : seen) {
        if (!v) return false;
    }
    return true;
}

