public int maxAbsoluteSum(int[] nums) {
    long maxEnding = 0, maxSum = Long.MIN_VALUE;
    long minEnding = 0, minSum = Long.MAX_VALUE;
    for (int num : nums) {
        maxEnding = Math.max(num, maxEnding + num);
        maxSum = Math.max(maxSum, maxEnding);
        minEnding = Math.min(num, minEnding + num);
        minSum = Math.min(minSum, minEnding);
    }
    long result = Math.max(Math.abs(maxSum), Math.abs(minSum));
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) return 0;
    int[] fibs = new int[50];
    fibs[0] = 1;
    fibs[1] = 1;
    int size = 2;
    while (true) {
        long next = (long) fibs[size - 1] + fibs[size - 2];
        if (next > k) break;
        fibs[size++] = (int) next;
    }
    int count = 0;
    int remain = k;
    for (int i = size - 1; i >= 0; i--) {
        if (remain >= fibs[i]) {
            remain -= fibs[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int diff = n / i;
            if (diff != i) {
                large.add(diff);
            }
        }
    }
    int smallSize = small.size();
    int largeSize = large.size();
    if (k <= smallSize) {
        return small.get(k - 1);
    }
    // remaining k is for large factors (in ascending order)
    int indexInLarge = k - smallSize - 1;
    if (indexInLarge < largeSize) {
        // large list is currently in descending order, so reverse index
        return large.get(largeSize - 1 - indexInLarge);
    }
    return -1;
}

