    for (String log : logs) {
        if ("../".equals(log)) {
            depth = Math.max(depth - 1, 0);
        } else if ("./".equals(log)) {
            continue;
        } else {
            depth++;
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    int extra = k - n;
    char[] chars = new char[n];
    Arrays.fill(chars, 'a');
    for (int i = n - 1; i >= 0 && extra > 0; i--) {
        int add = Math.min(25, extra);
        chars[i] += add;
        extra -= add;
    }
    return new String(chars);
}

