public static int singleNumber(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int sum = 0;
        for (int num : nums) {
            sum += (num >> i) & 1;
        }
        result |= (sum % 3) << i;
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    // Include 0 separately if within range
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }

    Queue<Long> queue = new LinkedList<>();
    // Initialize queue with numbers 1-9 as starting points
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long num = queue.poll();

        if (num > high) {
            continue;
        }

        if (num >= low) {
            result.add((int) num);
        }

        int lastDigit = (int) (num % 10);

        long next1 = num * 10 + (lastDigit - 1);
        long next2 = num * 10 + (lastDigit + 1);

        if (lastDigit > 0 && next1 <= high) {
            queue.offer(next1);
        }
        if (lastDigit < 9 && next2 <= high) {
            queue.offer(next2);
        }
    }

    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) return 0;
    long factor = 1;
    long count = 0;
    while (factor <= n) {
        long lower = n - (n / factor) * factor;
        long current = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

