public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) return 0;
    int m = mat.length, n = mat[0].length;
    int[][][] dp = new int[4][m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] != 1) {
                dp[0][i][j] = dp[1][i][j] = dp[2][i][j] = dp[3][i][j] = 0;
                continue;
            }
            dp[0][i][j] = (j > 0) ? dp[0][i][j - 1] + 1 : 1;             // horizontal
            dp[1][i][j] = (i > 0) ? dp[1][i - 1][j] + 1 : 1;             // vertical
            dp[2][i][j] = (i > 0 && j > 0) ? dp[2][i - 1][j - 1] + 1 : 1; // diagonal
            dp[3][i][j] = (i > 0 && j + 1 < n) ? dp[3][i - 1][j + 1] + 1 : 1; // anti-diagonal
            int current = Math.max(Math.max(dp[0][i][j], dp[1][i][j]),
                                   Math.max(dp[2][i][j], dp[3][i][j]));
            if (current > max) max = current;
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    String absStr = Integer.toString(Math.abs(n));
    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = absStr.length() - 1; i >= 0; i--) {
        sb.append(absStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }
    String result = sb.reverse().toString();
    if (negative) {
        result = "-" + result;
    }
    return result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    Arrays.sort(A);
    boolean[] used = new boolean[n];
    int[] count = new int[1];
    dfs(A, used, 0, -1, count);
    return count[0];
}

private static void dfs(int[] A, boolean[] used, int depth, int lastVal, int[] count) {
    int n = A.length;
    if (depth == n) {
        count[0]++;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue; // skip duplicates
        if (depth > 0 && !isPerfectSquare(lastVal + A[i])) continue;
        used[i] = true;
        dfs(A, used, depth + 1, A[i], count);
        used[i] = false;
    }
}

private static boolean isPerfectSquare(int sum) {
    int r = (int) Math.sqrt(sum);
    return r * r == sum;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        int curHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && curHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] res = new int[total];
    int index = 0;
    int maxSum = m + n - 2;
    for (int sum = 0; sum <= maxSum; sum++) {
        int iStart = Math.max(0, sum - (n - 1));
        int iEnd = Math.min(m - 1, sum);
        if ((sum & 1) == 0) {
            for (int i = iEnd; i >= iStart; i--) {
                int j = sum - i;
                res[index++] = mat[i][j];
            }
        } else {
            for (int i = iStart; i <= iEnd; i++) {
                int j = sum - i;
                res[index++] = mat[i][j];
            }
        }
    }
    return res;
}

public static int findSmallestInteger(int n) {
    String s = Integer.toString(n);
    char[] arr = s.toCharArray();
    int len = arr.length;
    int i = len - 2;
    while (i >= 0 && arr[i] >= arr[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = len - 1;
    while (arr[j] <= arr[i]) {
        j--;
    }
    char temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
    // reverse the subarray from i+1 to end
    int left = i + 1, right = len - 1;
    while (left < right) {
        char t = arr[left];
        arr[left] = arr[right];
        arr[right] = t;
        left++;
        right--;
    }
    try {
        return Integer.parseInt(new String(arr));
    } catch (NumberFormatException e) {
        return -1; // overflow case
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    String[][] pairs = {{"0", "0"}, {"1", "1"}, {"6", "9"}, {"8", "8"}, {"9", "6"}};
    List<String> prev = new ArrayList<>();
    prev.add("");
    for (int len = 2; len <= n; len++) {
        List<String> next = new ArrayList<>();
        for (String s : prev) {
            for (String[] pair : pairs) {
                String left = pair[0];
                String right = pair[1];
                if (len == n && left.equals("0")) {
                    continue; // avoid leading zeros for numbers longer than 1 digit
                }
                next.add(left + s + right);
            }
        }
        prev = next;
    }
    return prev;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length < 3) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Using cross product to check collinearity
    return (x2 - x1) * (y3 - y1) != (x3 - x1) * (y2 - y1);
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) return 0;
    int[] ugly = new int[n + 1];
    ugly[1] = 1;
    int i2 = 1, i3 = 1, i5 = 1;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 2; i <= n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n];
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    return Math.max(maxLen, currentLen);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>(n);
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, res);
    }
    return res;
}

private static void dfs(int current, int n, List<Integer> res) {
    res.add(current);
    int next = current * 10;
    while (next <= n) {
        dfs(next, n, res);
        next = next / 10 + 1;
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) return 0;
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = n + 1; // a large number greater than any possible answer
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int j = 1;
        while (j * j <= i) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
            j++;
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) return null;
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    if (word.length() > 0) {
        result.append(word.reverse());
    }
    return result.toString();
}
